python3 <<'EOF'
import json, statistics
from datetime import datetime

with open('/home/user/translation_updates.jsonl') as f:
    records = [json.loads(line) for line in f if line.strip()]

print('Total records:', len(records))

# Compute ratios and sort chronologically, handling empty timestamps by putting them at end
def sort_key(r):
    try:
        return (0, datetime.fromisoformat(r['timestamp']))
    except:
        return (1, datetime.min)

records_sorted = sorted(records, key=sort_key)
ratios = [len(r['target_text'])/max(1,len(r['source_text'])) for r in records_sorted]

# Verify all ANOM_ IDs get flagged with min_prior=10
for minp in [0, 1, 2, 5, 10, 30]:
    flags=[]
    for i in range(len(records_sorted)):
        w = ratios[max(0,i-30):i]
        if len(w) < minp:
            continue
        mu = statistics.mean(w)
        if len(w)>1:
            s = statistics.stdev(w)
        else:
            s = 0.0
        if abs(ratios[i]-mu) > 3*s:
            flags.append(records_sorted[i]['id'])
    anoms = [x for x in flags if x.startswith('ANOM_')]
    print(f'minp={minp}: total={len(flags)}, ANOM={len(anoms)}, nonANOM={len(flags)-len(anoms)}')
    if minp == 10:
        print('  flags sample:', flags[:10], '...', flags[-10:])
        print('  all ANOM?', [f'ANOM_{i:03d}' for i in range(50) if f'ANOM_{i:03d}' not in flags])
EOF
```

